import { tmpdir } from "node:os";
import { join } from "node:path";
import { test } from "node:test";
import { decideStatus, parseEvent, processEvent } from "../src/refunds.ts";
import { buildApp } from "../src/server.ts";
import { Store } from "../src/store.ts";
import { computeSignature, SignatureError, verifyReplay, verifyWebhook } from "../src/verify.ts";

const SECRET = "whsec_regression";
const POLICY = { auto_approve_max_minor: 500_000, auto_approve_currencies: ["INR"] };
const NOW = 1731920000;

function event(id = "evt_one", type = "refund.requested", amount = 100_000) {
  return { event_id: id, type, created: NOW,
    data: { refund_id: "rf_one", payment_id: "pay_one", amount, currency: "INR" } };
}

function signature(body: string | Buffer, timestamp = NOW, secret = SECRET): string {
  return `t=${timestamp},v1=${computeSignature(secret, timestamp, body)}`;
}

test("rotation accepts any active secret and v1 entry, but not an empty secret list", () => {
  const body = JSON.stringify(event());
  const header = `${signature(body, NOW, "wrong")},v1=${computeSignature(SECRET, NOW, body)}`;
  assert.doesNotThrow(() => verifyWebhook(body, header, ["old", SECRET], NOW));
  assert.throws(() => verifyWebhook(body, header, [], NOW), SignatureError);
});

test("HMAC covers exact bytes, including whitespace and non-ASCII content", () => {
  const body = Buffer.from(' { "message": "₹5,000" }\n');
  const header = signature(body);
  assert.doesNotThrow(() => verifyWebhook(body, header, [SECRET], NOW));
  assert.throws(() => verifyWebhook(JSON.stringify(JSON.parse(body.toString())), header, [SECRET], NOW), SignatureError);
  assert.throws(() => verifyWebhook(Buffer.concat([body, Buffer.from(" ")]), header, [SECRET], NOW), SignatureError);
});

test("normal and replay timestamps enforce inclusive tolerance in both directions", () => {
  const body = JSON.stringify(event());
  for (const offset of [-301, -300, 300, 301]) {
    const timestamp = NOW + offset;
    const normal = () => verifyWebhook(body, signature(body, timestamp), [SECRET], NOW);
    const replay = () => verifyReplay(body, String(timestamp), `v1=${computeSignature(SECRET, timestamp, body)}`, [SECRET], NOW);
    if (Math.abs(offset) <= 300) {
      assert.doesNotThrow(normal);
      assert.doesNotThrow(replay);
    } else {
      assert.throws(normal, SignatureError);
      assert.throws(replay, SignatureError);
    }
  }
});

test("missing and malformed signatures are rejected", () => {
  const body = "{}";
  for (const header of [undefined, "", `t=${NOW}`, `v1=${"a".repeat(64)}`,
    `t=${NOW},v1=bad`, `t=${NOW},v1=${"A".repeat(64)}`,
    `t=${NOW},t=${NOW},v1=${"a".repeat(64)}`,
    `t=999999999999999999999,v1=${"a".repeat(64)}`]) {
    assert.throws(() => verifyWebhook(body, header, [SECRET], NOW), SignatureError);
  }
});

// Snapshots include raw deliveries, state, and audit records, not just refund count.
function snapshot(dir: string): Record<string, string> {
  const result: Record<string, string> = {};
  for (const path of readdirSync(dir, { recursive: true, withFileTypes: true })) {
    if (path.isFile()) {
      const filename = join(path.parentPath, path.name);
      result[filename] = readFileSync(filename).toString("hex");
    }
  }
  return result;
}

async function withApp(run: (ctx: {
  store: Store;
  dir: string;
  post: (body: string, headers?: Record<string, string>) => Promise<Response>;
}) => Promise<void>): Promise<void> {
  const dir = mkdtempSync(join(tmpdir(), "pay381-"));
  const store = new Store(dir);
  const app = buildApp(store, { roles: {}, principals: {} }, POLICY,
    { webhook_secrets: ["old", SECRET], tolerance_s: 300, replay_tolerance_s: 86400 });
  const server = createServer((req, res) => void app(req, res));
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const url = `http://127.0.0.1:${(server.address() as AddressInfo).port}/webhooks/paygate`;
  try {
    await run({ store, dir, post: (body, headers = {}) => fetch(url, { method: "POST", body, headers }) });
  } finally {
    await new Promise<void>((resolve, reject) => server.close((err) => err ? reject(err) : resolve()));
    rmSync(dir, { recursive: true, force: true });
  }
}

test("HTTP rejects unauthenticated bodies without any writes and returns 400 for signed invalid events", async () => {
  await withApp(async ({ dir, post }) => {
    const before = snapshot(dir);
    const now = Math.floor(Date.now() / 1000);
    const body = JSON.stringify(event());
    for (const headers of [{}, { "paygate-signature": signature(body, now, "wrong") },
      { "paygate-signature": signature(body, now - 301) },
      { "paygate-signature": signature(body, now + 1000) }]) {
      const res = await post(body, headers);
      assert.equal(res.status, 401);
      await res.json();
      assert.deepEqual(snapshot(dir), before);
    }
    for (const invalid of ["{", "null", "{}", JSON.stringify(event("bad", "refund.requested", -1)),
      JSON.stringify({ ...event("bad"), created: "yesterday" })]) {
      const res = await post(invalid, { "paygate-signature": signature(invalid, now) });
      assert.equal(res.status, 400);
      await res.json();
      assert.deepEqual(snapshot(dir), before);
    }
  });
});

test("replays require fresh replay authentication, even with a widened legacy replay window", async () => {
  await withApp(async ({ store, dir, post }) => {
    const now = Math.floor(Date.now() / 1000);
    const old = now - 7200;
    const body = JSON.stringify(event());
    const original = { "paygate-signature": signature(body, old) };
    const before = snapshot(dir);
    const attempts = [
      { ...original, "x-replay-timestamp": String(now) },
      { ...original, "x-replay-timestamp": String(now), "x-replay-signature": `v1=${computeSignature("wrong", now, body)}` },
      { ...original, "x-replay-timestamp": String(old), "x-replay-signature": `v1=${computeSignature(SECRET, old, body)}` },
      { ...original, "x-replay-timestamp": "not-a-time", "x-replay-signature": `v1=${computeSignature(SECRET, now, body)}` },
      { "paygate-signature": signature(body, now), "x-replay-timestamp": String(now) },
    ];
    for (const headers of attempts) {
      const res = await post(body, headers);
      assert.equal(res.status, 401);
      await res.json();
      assert.deepEqual(snapshot(dir), before);
    }
    // The original signature is deliberately invalid: replay authentication stands alone.
    const headers = { "paygate-signature": "invalid", "x-replay-timestamp": String(now),
      "x-replay-signature": `v1=${"0".repeat(64)},v1=${computeSignature(SECRET, now, body)}` };
    const first = await post(body, headers);
    assert.equal(first.status, 200);
    assert.deepEqual(await first.json(), { received: true, duplicate: false });
    assert.equal(store.listRefunds().length, 1);
    const after = snapshot(dir);
    const second = await post(body, headers);
    assert.equal(second.status, 200);
    assert.deepEqual(await second.json(), { received: true, duplicate: true });
    assert.deepEqual(snapshot(dir), after);
  });
});

test("concurrent retries, altered duplicate bodies, and restarts do not repeat side effects", async () => {
  await withApp(async ({ dir, store, post }) => {
    const now = Math.floor(Date.now() / 1000);
    const body = JSON.stringify(event());
    const headers = { "paygate-signature": signature(body, now) };
    const responses = await Promise.all(Array.from({ length: 5 }, () => post(body, headers)));
    for (const response of responses) assert.equal(response.status, 200);
    const results = await Promise.all(responses.map((response) => response.json()));
    assert.equal(results.filter((result) => !result.duplicate).length, 1);
    assert.equal(store.listRefunds().length, 1);
    const before = snapshot(dir);
    const altered = JSON.stringify(event("evt_one", "refund.requested", 900_000));
    const duplicate = await post(altered, { "paygate-signature": signature(altered, now) });
    assert.deepEqual(await duplicate.json(), { received: true, duplicate: true });
    assert.equal(processEvent(new Store(dir), POLICY, parseEvent(body)).outcome, "duplicate");
    assert.deepEqual(snapshot(dir), before);
  });
});

test("ignored events and cancellations are deduplicated without repeating audits", async () => {
  const dir = mkdtempSync(join(tmpdir(), "pay381-processing-"));
  const store = new Store(dir);
  try {
    processEvent(store, POLICY, parseEvent(JSON.stringify(event())));
    const ignoredCancel = parseEvent(JSON.stringify(event("evt_cancel", "refund.cancelled")));
    assert.equal(processEvent(store, POLICY, ignoredCancel).outcome, "ignored");
    const unknown = parseEvent(JSON.stringify({ event_id: "evt_unknown", type: "future.event", created: NOW }));
    assert.equal(processEvent(store, POLICY, unknown).outcome, "ignored");
    const before = snapshot(dir);
    assert.equal(processEvent(store, POLICY, ignoredCancel).outcome, "duplicate");
    assert.equal(processEvent(store, POLICY, unknown).outcome, "duplicate");
    assert.deepEqual(snapshot(dir), before);
    assert.equal(store.listRefunds()[0].status, "auto_approved");
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("event IDs that match Object prototype names are not false duplicates", () => {
  const dir = mkdtempSync(join(tmpdir(), "pay381-ids-"));
  try {
    const store = new Store(dir);
    for (const id of ["constructor", "toString", "__proto__"]) {
      const ev = parseEvent(JSON.stringify(event(id)));
      assert.equal(processEvent(store, POLICY, ev).outcome, "processed");
      assert.equal(processEvent(new Store(dir), POLICY, ev).outcome, "duplicate");
    }
  } finally {
    rmSync(dir, { recursive: true, force: true });
  }
});

test("configured policy follows Dana's inclusive INR 5,000 threshold", () => {
  const policy = JSON.parse(readFileSync(new URL("../config/refunds.json", import.meta.url), "utf8"));
  assert.equal(policy.auto_approve_max_minor, 500_000);
  assert.deepEqual(policy.auto_approve_currencies, ["INR"]);
  assert.equal(decideStatus(policy, 499_999, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500_000, "INR"), "auto_approved");
  assert.equal(decideStatus(policy, 500_001, "INR"), "pending_review");
  assert.equal(decideStatus(policy, 1, "USD"), "pending_review");
});
